window.kbPageData["views/entry/k-646d833c5a188554"] = {"key":"entry/k-646d833c5a188554","state":{"route":"entry/k-646d833c5a188554"},"node":{"id":"k-646d833c5a188554","mode":"k","title":"民主集中制","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"seeAlso":["k-062abf0ddd85190c"],"directorySummary":"1.民主集中制\n民主集中制就是民主基础上的集中和集中指导下的民主相结合的制度。民主集中制\n包括民主和集中两个方面，两者互为条件、相辅相成、缺一不可。我们党实行的民主集中\n制，是又有集中又有民主、又有纪律又有自由、又有统一意志又有个人心情舒畅生动活泼\n的制度。\n民主集中制是马克思主义建党学说的重要内容…","sources":[{"id":"3cd0eab6f95914e6","label":"民主集中制","topic":"党政制度与理论","category":"非时政","text":"1.民主集中制\n民主集中制就是民主基础上的集中和集中指导下的民主相结合的制度。民主集中制\n包括民主和集中两个方面，两者互为条件、相辅相成、缺一不可。我们党实行的民主集中\n制，是又有集中又有民主、又有纪律又有自由、又有统一意志又有个人心情舒畅生动活泼\n的制度。\n民主集中制是马克思主义建党学说的重要内容。中国共产党从一开始就是按照民主\n集中制原则组织起来的。党的二大首次确认民主集中制的建党原则，党的六大通过的党章\n第一次明确规定党的组织原则是民主集中制。习近平总书记曾指出：民主集中制是我们党\n的根本组织制度和领导制度，是科学的合理的有效率的制度，是我们党最大的制度优势。\n民主集中制的基本原则：第一，坚持“四个服从”（即党员个人服从党的组织，少数\n服从多数，下级组织服从上级组织，全党各个组织和全体党员服从党的全国代表大会和中\n央委员会）；第二，坚持选举产生党的领导机关；第三，坚持集体领导；第四，善于发挥\n下级党组织的积极性；第五，注意尊重少数人意见；第六，禁止个人崇拜。","source":{"doc":"41195a191a57c1c36332","first":14,"last":15,"page":14,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{"k-062abf0ddd85190c":{"id":"k-062abf0ddd85190c","mode":"k","type":"制度与规则","title":"民主集中制的四个服从","qs":[],"count":0}},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-646d833c5a188554":[]}};
